#include <stdio.h>
#include <stdlib.h>

int main() {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    char **grid = (char**)malloc(N * sizeof(char*));
    for (int i = 0; i < N; i++) {
        grid[i] = (char*)malloc((M + 1) * sizeof(char));
        scanf("%s", grid[i]);
    }

    int start_i = 0, start_j = 0;
    for (int j = 0; j < M; j++) {
        if (grid[0][j] == 'o') {
            start_j = j;
            break;
        }
    }

    int max_cells = N * M;
    int *q_i = (int*)malloc(max_cells * sizeof(int));
    int *q_j = (int*)malloc(max_cells * sizeof(int));
    int front = 0, rear = 0;

    q_i[rear] = start_i;
    q_j[rear] = start_j;
    rear++;

    while (front < rear) {
        int i = q_i[front];
        int j = q_j[front];
        front++;

        // Vertical flow downwards
        if (i + 1 < N && grid[i+1][j] == '.') {
            grid[i+1][j] = 'o';
            q_i[rear] = i + 1;
            q_j[rear] = j;
            rear++;
        }

        // Horizontal spread if there is a shelf directly below
        if (i + 1 < N && grid[i+1][j] == '#') {
            if (j - 1 >= 0 && grid[i][j-1] == '.') {
                grid[i][j-1] = 'o';
                q_i[rear] = i;
                q_j[rear] = j - 1;
                rear++;
            }
            if (j + 1 < M && grid[i][j+1] == '.') {
                grid[i][j+1] = 'o';
                q_i[rear] = i;
                q_j[rear] = j + 1;
                rear++;
            }
        }
    }

    for (int i = 0; i < N; i++) {
        printf("%s\n", grid[i]);
    }

    for (int i = 0; i < N; i++) free(grid[i]);
    free(grid);
    free(q_i);
    free(q_j);

    return 0;
}
